'use strict';

var index = require('./index-OWCBTetj.js');

const segmentCss = () => `.segment{display:flex;align-items:center;justify-content:center;gap:8px;position:relative;border:1px solid #bfbbbb;border-radius:1px;padding:0 8px 0 8px;height:34px;background-color:#ffffff;transition:all 100ms ease;transition-property:color, background;font:600 0.875rem/1.25rem "Source Sans 3";font-family:var(--ifx-font-family)}.segment:focus-visible{color:#ffffff;background-color:#0a8276}.segment:hover{color:#ffffff;background-color:#08665c;cursor:pointer}.segment:active{background-color:#06534b}.segment.segment--selected{color:#ffffff;background-color:#0a8276}.segment.segment--small{height:30px}.segment::after{position:absolute;top:0;left:0;width:100%;height:100%;outline:1px solid #bfbbbb;border-radius:1px;content:""}`;

const Segment = class {
    constructor(hostRef) {
        index.registerInstance(this, hostRef);
        this.segmentSelect = index.createEvent(this, "segmentSelect", 5);
    }
    /** Fired when this segment is selected (emits the segment index). */
    segmentSelect;
    /** Icon to display inside the segment. */
    icon;
    /** Index of this segment within the segmented control. */
    segmentIndex;
    /** Whether this segment is currently selected. */
    selected = false;
    /** Value associated with this segment. */
    value;
    handleSegmentClick() {
        if (this.selected)
            return;
        this.selected = true;
        this.segmentSelect.emit(this.segmentIndex);
    }
    handleSegmentKeyDown(event) {
        if (event.code === "Enter" || event.code === "Space") {
            if (this.selected)
                return;
            this.selected = true;
            this.segmentSelect.emit(this.segmentIndex);
        }
    }
    render() {
        return (index.h("div", { key: 'e6c9f9e67f7f06ce0b81a1eaa59f83d0981b91c7', class: `segment ${this.selected ? "segment--selected" : ""}`, tabIndex: 0, onClick: () => {
                this.handleSegmentClick();
            }, onKeyDown: (e) => {
                this.handleSegmentKeyDown(e);
            } }, index.h("ifx-icon", { key: 'f57a44b5a0fbb6aa0d100a98efc1f1d8c197e3b2', icon: this.icon }), " ", index.h("slot", { key: 'c64c2f148cb8f88c3b59aacac613ef336ed60ef5' })));
    }
};
Segment.style = segmentCss();

exports.ifx_segment = Segment;
